#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, rotation, vf, hf;
    if (scanf("%d %d %d %d", &n, &rotation, &vf, &hf) != 4) return 0;
    vector<vector<int>> a(n, vector<int>(n));
    for (auto &row : a)
        for (auto &x : row) scanf("%d", &x);
    for (int t = 0; t < rotation / 90; t++) {
        // clockwise 90 degrees: b[i][j] = a[n-1-j][i]
        vector<vector<int>> b(n, vector<int>(n));
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) b[i][j] = a[n - 1 - j][i];
        a.swap(b);
    }
    if (vf) reverse(a.begin(), a.end());
    if (hf)
        for (auto &row : a) reverse(row.begin(), row.end());
    string out;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (j) out += ' ';
            out += to_string(a[i][j]);
        }
        out += '\n';
    }
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), rotation = nextInt(), vf = nextInt(), hf = nextInt();
        int[][] a = new int[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) a[i][j] = nextInt();
        for (int t = 0; t < rotation / 90; t++) {
            // clockwise 90 degrees: b[i][j] = a[n-1-j][i]
            int[][] b = new int[n][n];
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++) b[i][j] = a[n - 1 - j][i];
            a = b;
        }
        if (vf == 1)
            for (int i = 0, j = n - 1; i < j; i++, j--) {
                int[] t = a[i]; a[i] = a[j]; a[j] = t;
            }
        if (hf == 1)
            for (int[] row : a)
                for (int i = 0, j = n - 1; i < j; i++, j--) {
                    int t = row[i]; row[i] = row[j]; row[j] = t;
                }
        StringBuilder sb = new StringBuilder();
        for (int[] row : a) {
            for (int j = 0; j < n; j++) {
                if (j > 0) sb.append(' ');
                sb.append(row[j]);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, rotation, vf, hf := int(nextInt()), int(nextInt()), nextInt(), nextInt()
	a := make([][]byte, n)
	for i := range a {
		a[i] = make([]byte, n)
		for j := range a[i] {
			a[i][j] = byte('0' + nextInt())
		}
	}
	for t := 0; t < rotation/90; t++ {
		// clockwise 90 degrees: b[i][j] = a[n-1-j][i]
		b := make([][]byte, n)
		for i := range b {
			b[i] = make([]byte, n)
			for j := range b[i] {
				b[i][j] = a[n-1-j][i]
			}
		}
		a = b
	}
	if vf == 1 {
		slices.Reverse(a)
	}
	if hf == 1 {
		for _, row := range a {
			slices.Reverse(row)
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for _, row := range a {
		for j, c := range row {
			if j > 0 {
				w.WriteByte(' ')
			}
			w.WriteByte(c)
		}
		w.WriteByte('\n')
	}
}
